"use client";

import {
  type AnimationOptions,
  type AnimationPlaybackControls,
  type DOMKeyframesDefinition,
  useAnimate,
  useReducedMotion,
} from "motion/react";
import { useEffect, useRef } from "react";

// Generated by strokekit. Colors follow --sk-stroke; prefers-reduced-motion shows the final frame.
const css = `
.sk-11gvtka-0 {
  stroke: var(--sk-stroke, #4f46e5);
  stroke-dasharray: 1 1;
  stroke-dashoffset: 1;
  fill-opacity: 0;
}
.sk-11gvtka-1 {
  stroke: var(--sk-stroke, #a5b4fc);
  stroke-dasharray: 1 1;
  stroke-dashoffset: 1;
  fill-opacity: 0;
}
.sk-11gvtka-2 {
  stroke: var(--sk-stroke, #f59e0b);
  stroke-dasharray: 1 1;
  stroke-dashoffset: 1;
  fill-opacity: 0;
}
@media (prefers-reduced-motion: reduce) {
  .sk-11gvtka * {
    animation: none;
  }
  .sk-11gvtka-0 {
    stroke-dashoffset: 0;
    fill-opacity: 1;
  }
  .sk-11gvtka-1 {
    stroke-dashoffset: 0;
    fill-opacity: 1;
  }
  .sk-11gvtka-2 {
    stroke-dashoffset: 0;
    fill-opacity: 1;
  }
}
`;

type Track = { selector: string; keyframes: DOMKeyframesDefinition; options: AnimationOptions };

const tracks: Track[] = [
  {
    selector: ".sk-11gvtka-0",
    keyframes: {
      strokeDashoffset: [1, 0, 0],
      fillOpacity: [0, 0, 1],
    },
    options: {
      duration: 2,
      delay: 0,
      ease: "easeInOut",
      times: [0, 0.6, 1],
      repeat: 0,
      repeatType: "loop",
    },
  },
  {
    selector: ".sk-11gvtka-1",
    keyframes: {
      strokeDashoffset: [1, 0, 0],
      fillOpacity: [0, 0, 1],
    },
    options: {
      duration: 2,
      delay: 0,
      ease: "easeInOut",
      times: [0, 0.6, 1],
      repeat: 0,
      repeatType: "loop",
    },
  },
  {
    selector: ".sk-11gvtka-2",
    keyframes: {
      strokeDashoffset: [1, 0, 0],
      fillOpacity: [0, 0, 1],
    },
    options: {
      duration: 2,
      delay: 0,
      ease: "easeInOut",
      times: [0, 0.6, 1],
      repeat: 0,
      repeatType: "loop",
    },
  },
];

export type OrbitaMotionLogoProps = {
  /** Width and height (number = px). Defaults to the SVG's own size. */
  size?: number | string;
  /** Playback speed multiplier: 2 plays twice as fast. */
  speed?: number;
  /** true repeats forever, false plays once. Defaults to the exported animation. */
  loop?: boolean;
  paused?: boolean;
  className?: string;
  /** Accessible name. Defaults to "Órbita". */
  label?: string;
};

export function OrbitaMotionLogo({
  size,
  speed = 1,
  loop,
  paused = false,
  className,
  label = "Órbita",
}: OrbitaMotionLogoProps) {
  const [scope, animate] = useAnimate<SVGSVGElement>();
  const reducedMotion = useReducedMotion();
  const controls = useRef<AnimationPlaybackControls[]>([]);

  useEffect(() => {
    if (reducedMotion) return;
    controls.current = tracks.map((track) =>
      animate(track.selector, track.keyframes, {
        ...track.options,
        ...(loop === undefined ? {} : { repeat: loop ? Number.POSITIVE_INFINITY : 0 }),
      }),
    );
    return () => {
      for (const control of controls.current) control.stop();
      controls.current = [];
    };
  }, [animate, loop, reducedMotion]);

  useEffect(() => {
    for (const control of controls.current) {
      control.speed = speed;
      if (paused) control.pause();
      else control.play();
    }
  }, [speed, paused, loop, reducedMotion]);

  return (
    <svg
      viewBox="0 0 160 160"
      width={size ?? 160}
      height={size ?? 160}
      className={className ? `sk-11gvtka ${className}` : "sk-11gvtka"}
      ref={scope}
      role="img"
      aria-label={label}
    >
      <style>{css}</style>
      <title>{"Órbita"}</title>
      <g fill="none" stroke="#4f46e5" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="80" cy="80" r="58" pathLength="1" className="sk-11gvtka-0" />
        <ellipse cx="80" cy="80" rx="72" ry="26" transform="rotate(-28 80 80)" stroke="#a5b4fc" strokeWidth="4" pathLength="1" className="sk-11gvtka-1" />
        <path d="M58 92 C 62 70, 76 60, 98 62" pathLength="1" className="sk-11gvtka-0" />
        <circle cx="126" cy="46" r="9" stroke="#f59e0b" pathLength="1" className="sk-11gvtka-2" />
      </g>
    </svg>
  );
}
